"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["45643"],{40426(e,t,i){i.d(t,{Ay:()=>a,RM:()=>s});var n=i(74848),o=i(28453);let s=[];function r(e){let t={blockquote:"blockquote",h1:"h1",header:"header",p:"p",...(0,o.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"some-words-i-want-to-say-to-humanity-present-and-future",children:"Some Words I Want to Say: To Humanity, Present and Future"})}),"\n",(0,n.jsxs)(t.blockquote,{children:["\n",(0,n.jsx)(t.p,{children:"2008/5/25 15:13:09"}),"\n"]}),"\n",(0,n.jsxs)("div",{style:{color:"#000066",fontSize:"22px",fontWeight:"500",lineHeight:"180%"},children:[(0,n.jsx)(t.p,{children:"This illness, honestly, was not something this ID had anticipated. This ID has no supernatural powers \u2014 just an ordinary person. Only a person who will never consent to anything but standing upright, and who hopes to explore and demonstrate all of humanity's potential and possibility."}),(0,n.jsx)(t.p,{children:"I once said that as long as everything goes smoothly, after turning 40, this ID would contribute some effort to the construction of culture. At that point, the real this ID and the virtual this ID would naturally correspond. Therefore, all of this ID's experiences are being truthfully recorded. In the future, they will become part of this ID's real biography."})]}),"\n",(0,n.jsx)("div",{style:{color:"#000066",fontSize:"14px",fontWeight:"500"},children:(0,n.jsx)(t.p,{children:"Only after 40 does a person truly stand on their own feet. This ID has no desire to be anyone's teacher. It is simply that many phenomena and theories are too absurd. Knowledge belongs to all humankind. If this ID has a different perspective, of course it can be offered."})}),"\n",(0,n.jsx)("div",{style:{color:"#000066",fontSize:"22px",fontWeight:"500",lineHeight:"180%"},children:(0,n.jsx)(t.p,{children:"This ID has always felt that what I say is merely one person's opinion. Unifying words and deeds \u2014 this ID records his own life, and that too is part of speech."})}),"\n",(0,n.jsx)("div",{style:{color:"#000066",fontSize:"14px",fontWeight:"500"},children:(0,n.jsx)(t.p,{children:"Direct realization \u2014 everything must be thus. A person is born into deception. Your culture, the preconditions of your existence, all constitute the so-called axioms of your life system. And axioms are often the fraud."})}),"\n",(0,n.jsxs)("div",{style:{color:"#000066",fontSize:"22px",fontWeight:"500",lineHeight:"180%"},children:[(0,n.jsx)(t.p,{children:"If one truly wants to live life clearly, the first 30 or 40 years must be spent breaking through this fraud. Of course, since the beginning of recorded history, the number of people who have truly managed this can probably be counted on one hand. The vast majority of people merely pass through their entire lives immersed in deception."}),(0,n.jsx)(t.p,{children:"Modern people are even more so. We are all, first and foremost, those who eat with our ears. Ultimately we select one thing to believe in, then like opium addicts, we are done for life."}),(0,n.jsx)(t.p,{children:"The vast majority of people live their entire lives in conformity. And at moments of historical upheaval, there appear so-called heroes and revolutions. These constitute history. Some people wish to transcend the human ladder, and thus cultivation comes into being."}),(0,n.jsx)(t.p,{children:"If the human is only human, then how to settle one's life is merely an aesthetic question. If the human has the possibility of transcendence, then the human being is a genuine life-practice."}),(0,n.jsx)(t.p,{children:"Between these two choices, the first is the choice of the vast majority. Therefore, most people live according to their own aesthetic standards \u2014 that is, they have given up the search upward and downward. After all, that is an extremely painful, extremely insoluble game."}),(0,n.jsx)(t.p,{children:"And the most vile are those who claim to have personally realized that humans can transcend, and then swindle real-world benefits. This is a gimmick."}),(0,n.jsx)(t.p,{children:"The vast majority of history is composed of various grades of hype. Hype includes slogans, religions, theories, and so on and so forth."}),(0,n.jsx)(t.p,{children:"Of course, a large part of human culture has aesthetically appropriated the practices of cultivators. For example, Zen-influenced culture \u2014 without this aesthetic appropriation, a large portion of Chinese culture would lose its luster."}),(0,n.jsx)(t.p,{children:"But this appropriation turns genuine direct realization into a humanized aesthetic, transforms the blood-traces ground out by countless cultivators with their lives into decorative lines for adorning one's so-called refinement \u2014 and this becomes yet another fraud."}),(0,n.jsx)(t.p,{children:"Future humanity should clearly tell its descendants, educating them this way. First: we are human. The culture and life we possess are merely the axiomatized system of a human being. What exists beyond this system requires each person's own life to transcend."}),(0,n.jsx)(t.p,{children:"Tell every person who becomes human \u2014 for example, in the very first lecture at university \u2014 that your life can have only two possible choices. One is the aesthetic mode, which includes everything from the economic-animal style, the revolutionary style, to the roaming-freely-between-heaven-and-earth style \u2014 but these are all aesthetic forms of human existence. The other \u2014 the practice of transcending the human axiom system \u2014 is not something every person needs to choose."}),(0,n.jsx)(t.p,{children:"Of course, since one is human, one must shoulder human responsibility. What this ID is doing now does not even count as the giving of dharma. It is merely a live demonstration of some experimental results within the axiom system of worldly dharma."})]}),"\n",(0,n.jsx)("div",{style:{color:"#000066",fontSize:"14px",fontWeight:"500"},children:(0,n.jsx)(t.p,{children:"This demonstration can be precisely recorded in its truth. For those who are interested, you can record one of this ID's activity changes: tomorrow this ID will leave the traditional Chinese medicine hospital to go out and about. When the day comes that the real this ID is identified, you can check the hospital records."})}),"\n",(0,n.jsxs)("div",{style:{color:"#000066",fontSize:"22px",fontWeight:"500",lineHeight:"180%"},children:[(0,n.jsx)(t.p,{children:"This ID approaches this experiment with mathematical rigor."}),(0,n.jsx)(t.p,{children:"Here is another fact that can be told and has already been recorded: after two injections of imported white-blood-cell-boosting medication at 1,800 yuan each, the white blood cell count went from 1,000 to 1,400. Then two more injections brought it to 2,900. This ID borrowed the force of these four injections over two days. On the morning of the third day, I was able to sit up and enter the most rudimentary state of zazen, roughly opening the channels throughout the body \u2014 mainly clearing the spinal column. After one more injection on the third day, the result was 12,000. That is why this ID can now write such a long article."}),(0,n.jsx)(t.p,{children:"This ID's life-operation game has certainly not yet succeeded, and there is certainly still a possibility of failure. If it fails, at the final moment of failure, this ID will publicly reveal the real identity, so that a complete life record can serve as experience for future generations."}),(0,n.jsx)(t.p,{children:"However, if it does fail, many things this ID has already formulated will not be able to be written down. But this ID's view is: if one cannot even play the life-experiment game, then the theories this person has developed are just another piece of garbage theory among the existing multitude \u2014 losing it is no great loss."}),(0,n.jsx)(t.p,{children:"One of the biggest surprises this time \u2014 perhaps due to some good karma from the past \u2014 is that this ID's biological brother has reached a very high level of understanding in Chinese medicine, and has been of great help to this ID. Previously, this ID mentioned that three bowls of herbal soup were able to turn this ID around \u2014 that was his doing. After all, this requires a person to carry it out, and how many people in the world are capable? Of course, in the broader picture, he still has deficiencies. But in the specifics of herbal prescription, at least his starting point is correct. Medicine should be used this way, not the way the vast majority of current Chinese medicine practitioners do it \u2014 they use dead medicine."}),(0,n.jsx)(t.p,{children:"In Chinese medicine, this ID has an extremely elevated perspective but has had little opportunity for practice \u2014 one can hardly snatch someone off the street for practice. His having been secretly working at it for N years was a great surprise to this ID. However, his aspirations do not lie in practicing medicine \u2014 he is the Daoist-hermit type, a lazy sort."}),(0,n.jsx)(t.p,{children:"So if this ID fails this time, it can also add a question mark to Chinese medicine."}),(0,n.jsx)(t.p,{children:"This ID is now writing these things with the attitude of a scientific experiment."}),(0,n.jsx)(t.p,{children:"Experimental report \u2014 interim summary. Everything that should be written has been written. Pressing pause here."})]})]})}function a(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(r,{...e})}):r(e)}},9260(e,t,i){i.r(t),i.d(t,{metadata:()=>n,default:()=>u,frontMatter:()=>a,contentTitle:()=>h,toc:()=>c,assets:()=>l});var n=JSON.parse('{"id":"stocks/tohuman","title":"","description":"","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/stocks/tohuman.md","sourceDirName":"stocks","slug":"/stocks/tohuman","permalink":"/en/stocks/tohuman","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"tohuman","title":"","hide_table_of_contents":true,"sidebar_label":"Some Words I Want to Say: To Present and Future Humanity (2008/5/25 15:13:09)"},"sidebar":"stocksExtendedSidebar","previous":{"title":"Chemotherapy Starts Tomorrow (2008/5/10 17:00:19)","permalink":"/en/stocks/swansong"},"next":{"title":"Rare to Be Muddled, Rare to Be Ill (2008/6/3 12:13:16)","permalink":"/en/stocks/woollyheaded"}}'),o=i(74848),s=i(28453),r=i(40426);let a={id:"tohuman",title:"",hide_table_of_contents:!0,sidebar_label:"Some Words I Want to Say: To Present and Future Humanity (2008/5/25 15:13:09)"},h,l={},c=[...r.RM];function d(e){return(0,o.jsx)(r.Ay,{})}function u(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(d,{...e})}):d(e)}},28453(e,t,i){i.d(t,{R:()=>r,x:()=>a});var n=i(96540);let o={},s=n.createContext(o);function r(e){let t=n.useContext(s);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:r(e.components),n.createElement(s.Provider,{value:t},e.children)}}}]);